/** A file of tables, browsed — driven by a `TableCatalog` and nothing
 *  else.
 *
 *  This component doesn't know whether the engine answering it is
 *  running in this tab, in a Cloudflare Worker next to the bytes, or on
 *  a machine with a native `sqlite3`. That's the whole point of the
 *  catalog: the three deployment modes differ in a line of wiring, not
 *  in a UI.
 *
 *  It also doesn't know what the engine *is*. A backend serving the
 *  same two endpoints from DuckDB or Postgres gets this view for free.
 *
 *  Controls follow `TableSource['capabilities']`, and follow them by
 *  being **absent rather than disabled** — the same rule the parquet
 *  viewer uses above its size threshold. A sort arrow that does nothing
 *  when clicked is worse than no arrow.
 */
import {
  useEffect, useMemo, useRef, useState,
  type CSSProperties, type ReactNode,
} from 'react'
import type { PersistedState } from '../react/persistedState'
import { defaultUseState } from '../react/persistedState'
import {
  resolveColStyles, resolveElide, TD_STYLE, TH_STYLE,
  type TableColumn, type TablePageCtx, type TableViewerOptions,
} from './table'
import { PathNote, TableRows } from './tableBody'
import { pathModes } from './tableRuns'
import { ColumnResizeHandle, useColumnWidths } from './columnResize'
import type { PageResult, TableCatalog, TableObject } from './tableSource'
import { ColumnPicker, FilterInput, useColumnVisibility, useFilter, usePageNotify } from './tableControls'
import { sortGlyph, useSort } from './tableSort'

/** Rows per page.
 *
 *  Larger than the parquet viewer's row-group pages because the cost is
 *  different in kind: another hundred rows is a longer `LIMIT` against
 *  pages the engine is already holding, not another range request. */
export const DEFAULT_PAGE_SIZE = 100

export const BTN: CSSProperties = {
  font: 'inherit', fontSize: '0.85em', lineHeight: 1.4, cursor: 'pointer',
  padding: '0.15em 0.5em', borderRadius: 3, color: 'inherit',
  border: '1px solid rgba(127,127,127,0.4)', background: 'transparent',
}

export interface TableBrowserOptions extends Omit<TableViewerOptions, 'fullLoadMaxBytes' | 'sortComparators'> {
  pageSize?: number
  /** Extra chrome for the summary line — a read counter, a latency
   *  readout, whatever the wiring can say that this component can't. */
  status?: ReactNode
}

const ROW_STYLE: CSSProperties = { borderTop: '1px solid rgba(127,127,127,0.15)' }

const NUMERIC_KINDS = new Set<TableColumn['kind']>(['number'])

const plural = (n: number, noun: string) => `${n.toLocaleString()} ${noun}${n === 1 ? '' : 's'}`

/** Render a value the way the engine handed it over.
 *
 *  `null` is shown rather than left blank: in a database the difference
 *  between NULL and the empty string is meaningful, and a blank cell
 *  reads as neither. */
export function defaultTableCell(value: unknown): ReactNode {
  if (value === null || value === undefined) {
    return <span style={{ opacity: 0.4 }}>null</span>
  }
  if (value instanceof Uint8Array) {
    return <span style={{ opacity: 0.6 }}>{`<${value.byteLength} bytes>`}</span>
  }
  return String(value)
}

export function TableBrowser({
  catalog, objects, path, usePersistedState, pageSize = DEFAULT_PAGE_SIZE, status,
  renderCell, renderHeader, cellProps, headerProps,
  columnPicker = false, hiddenColumns, ditto, paths, groups, onPage, onCellHover, elide, resizableColumns = false,
}: {
  catalog: TableCatalog
  /** Already fetched by the wiring, which had to open the file anyway. */
  objects: readonly TableObject[]
  path: string
  usePersistedState?: PersistedState
} & TableBrowserOptions) {
  const use = usePersistedState ?? defaultUseState

  const [table, setTable] = use<string>('table', '')
  const [page, setPage] = use<number>('page', 0)
  const [filter, setFilter] = useFilter(usePersistedState)
  const sort = useSort(usePersistedState)

  const [result, setResult] = useState<PageResult | null>(null)
  const [error, setError] = useState<Error | null>(null)
  const [loading, setLoading] = useState(false)

  /** The table actually shown: the URL's, when this file has it, else
   *  the first. A `?table=` pasted across files should land somewhere
   *  rather than on an error. */
  const active = useMemo(
    () => objects.find(o => o.name === table) ?? objects[0] ?? null,
    [objects, table])

  const source = useMemo(
    () => (active ? catalog.source(active.name) : null),
    [catalog, active])
  const can = source?.capabilities

  const columns = result?.columns ?? []
  const { visible, ...vis } = useColumnVisibility(columns, usePersistedState, hiddenColumns)

  useEffect(() => {
    if (!source) return
    let live = true
    setLoading(true)
    source
      .page({
        offset: page * pageSize,
        limit: pageSize,
        ...(can?.filter ? { filter } : {}),
        ...(can?.sort && sort.column ? { sort: { column: sort.column, dir: sort.dir } } : {}),
      })
      .then(r => { if (live) { setResult(r); setError(null) } })
      .catch(e => { if (live) setError(e instanceof Error ? e : new Error(String(e))) })
      .finally(() => { if (live) setLoading(false) })
    return () => { live = false }
  }, [source, page, pageSize, filter, sort.column, sort.dir, can?.filter, can?.sort])

  // Reset to the first page whenever the shape of the query changes —
  // page 40 of an unfiltered table is rarely page 40 of a filtered one.
  //
  // Not on mount, though: seeding the ref with `null` and adopting the
  // first key means "changed" means changed *since this view opened*,
  // which is what keeps a shared `?page=` intact.
  const queryKey = `${active?.name ?? ''}�${filter}�${sort.column ?? ''}${sort.dir}`
  const lastQueryKey = useRef<string | null>(null)
  useEffect(() => {
    if (lastQueryKey.current !== null && lastQueryKey.current !== queryKey) setPage(0)
    lastQueryKey.current = queryKey
  }, [queryKey, setPage])

  const rows = result?.rows ?? []
  const total = result?.total ?? null
  const pageStart = result?.offset ?? 0

  // The unfiltered total, remembered per table, so the filter can read
  // `12 / 900` rather than `12 / 12`. Only ever learned by having been
  // unfiltered at some point — landing on a filtered URL means the
  // denominator is genuinely unknown, and inventing one by counting
  // again would be a scan nobody asked for.
  const unfilteredTotals = useRef(new Map<string, number>())
  if (active && !filter.trim() && total !== null) unfilteredTotals.current.set(active.name, total)
  const unfilteredTotal = active ? unfilteredTotals.current.get(active.name) : undefined

  const el = useMemo(() => resolveElide(elide), [elide])
  const cw = useColumnWidths({
    on: !!resizableColumns,
    scope: typeof resizableColumns === 'object' ? (resizableColumns.scope ?? 'path') : 'path',
    columns, path, usePersistedState,
  })
  const colStyles = useMemo(
    () => resolveColStyles(columns, path, { cellProps, headerProps }, c => NUMERIC_KINDS.has(c.kind), el),
    [columns, path, cellProps, headerProps, el])

  // Outward-facing hooks, called before any early return: a hook after
  // a conditional `return` runs on some renders and not others, which
  // React rejects outright. The page they describe is derived above, so
  // it's passed by ref and read when the effect fires.
  const pageCtxRef = useRef<TablePageCtx>({ rows: [], columns: [], path, pageStart: 0, totalRows: null })
  pageCtxRef.current = {
    rows,
    columns: columns.filter(c => visible.includes(c.name)),
    path,
    pageStart,
    totalRows: total,
  }
  usePageNotify(onPage, pageCtxRef, [rows, visible, path, pageStart, total])

  if (!objects.length) return <div style={{ opacity: 0.6 }}>no tables or views in this file</div>

  const lastPage = total === null ? null : Math.max(0, Math.ceil(total / pageSize) - 1)
  const shown = columns.filter(c => visible.includes(c.name))
  const pathNotes = paths ? pathModes(rows, shown, paths).notes : undefined

  return (
    <div>
      {/* Positioned so the column picker's panel can paint over the
          sticky header — a z-index on the picker alone can't, since it
          is a flex item of this line and paints in the line's place in
          the root stacking order. */}
      <p style={{
        opacity: 0.85, fontSize: '0.95em', display: 'flex', alignItems: 'center',
        gap: '0.6em', flexWrap: 'wrap', position: 'relative', zIndex: 2,
      }}>
        {objects.length > 1 && (
          <select
            value={active?.name ?? ''}
            onChange={e => setTable(e.target.value)}
            aria-label="Table"
            style={{ ...BTN, cursor: 'pointer' }}
          >
            {objects.map(o => (
              <option key={o.name} value={o.name}>
                {o.name}{o.type === 'view' ? ' (view)' : ''}
              </option>
            ))}
          </select>
        )}
        {/* Nothing until the first result: "0 rows" while a query is
            still running reads as an answer, and it's the wrong one. */}
        {result && (
          <span style={{ opacity: 0.7 }}>
            {plural(total ?? rows.length, 'row')}
            {total !== null && total > 0 && ` · ${(pageStart + 1).toLocaleString()}–${(pageStart + rows.length).toLocaleString()}`}
          </span>
        )}
        {can?.filter && (
          <FilterInput
            value={filter}
            onChange={setFilter}
            placeholder="filter"
            {...(total !== null && unfilteredTotal !== undefined
              ? { count: { shown: total, total: unfilteredTotal } }
              : {})}
          />
        )}
        {columnPicker && columns.length > 0 && <ColumnPicker columns={columns} vis={{ visible, ...vis }} />}
        {loading && <span style={{ opacity: 0.5 }}>…</span>}
        {status}
      </p>

      {error && (
        <p style={{ color: 'crimson', fontSize: '0.9em' }}>{error.message}</p>
      )}

      <div style={{ overflowX: 'auto', maxHeight: '70vh', overflowY: 'auto' }}>
        <table style={{ borderCollapse: 'collapse', fontSize: '0.82em', fontFamily: 'ui-monospace, monospace' }}>
          <thead>
            <tr style={{
              position: 'sticky', top: 0, zIndex: 1,
              background: 'linear-gradient(rgba(127,127,127,0.15), rgba(127,127,127,0.15)), Canvas',
            }}>
              {shown.map(c => {
                const styles = colStyles.get(c.name)
                const label = can?.sort
                  ? (
                    <span
                      onClick={() => sort.toggle(c.name)}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title={`Sort by ${c.name}`}
                    >
                      {c.name}{' '}
                      <span style={{ opacity: sort.column === c.name ? 0.9 : 0.3 }}>
                        {sortGlyph(c.name, sort)}
                      </span>
                    </span>
                  )
                  : <span>{c.name}</span>
                return (
                  <th
                    key={c.name}
                    style={{ ...(styles?.header ?? TH_STYLE), ...(resizableColumns ? { position: 'relative' } : {}), ...cw.styleFor(c.name) }}
                    {...(styles?.headerClass ? { className: styles.headerClass } : {})}
                  >
                    {renderHeader ? renderHeader({ column: c, path, defaultNode: label }) : label}
                    <PathNote note={pathNotes?.get(c.name)} onSort={can?.sort ? () => sort.toggle(c.name) : undefined} />
                    {resizableColumns && <ColumnResizeHandle col={c.name} widths={cw} />}
                  </th>
                )
              })}
            </tr>
          </thead>
          <TableRows
            rows={rows}
            columns={shown}
            path={path}
            colStyles={colStyles}
            widthStyle={cw.styleFor}
            el={el}
            {...(ditto ? { ditto } : {})}
            {...(paths ? { paths } : {})}
            {...(groups ? { groups } : {})}
            {...(usePersistedState ? { usePersistedState } : {})}
            {...(renderCell ? { renderCell } : {})}
            defaultNode={defaultTableCell}
            rowIndex={i => pageStart + i}
            rowKey={i => pageStart + i}
            rowStyle={ROW_STYLE}
            {...(onCellHover ? { onCellHover } : {})}
          >
            {result && rows.length === 0 && !loading && !error && (
              <tr>
                <td colSpan={Math.max(1, shown.length)} style={{ ...TD_STYLE, opacity: 0.6 }}>
                  {filter.trim() ? 'no rows match' : 'no rows'}
                </td>
              </tr>
            )}
          </TableRows>
        </table>
      </div>

      <p style={{ display: 'flex', alignItems: 'center', gap: '0.5em', marginTop: '0.6em' }}>
        <button type="button" style={BTN} disabled={page === 0} onClick={() => setPage(page - 1)}>‹ prev</button>
        <span style={{ opacity: 0.7, fontSize: '0.85em' }}>
          {/* Without random access there are no page *numbers* to show —
              the source can't be asked how many there are, and a count
              that only grows as you walk is worse than none. */}
          {can?.randomAccess === false
            ? `rows ${(pageStart + 1).toLocaleString()}–${(pageStart + rows.length).toLocaleString()}`
            : `page ${(page + 1).toLocaleString()}${lastPage !== null ? ` / ${(lastPage + 1).toLocaleString()}` : ''}`}
        </span>
        <button
          type="button"
          style={BTN}
          disabled={lastPage !== null ? page >= lastPage : rows.length < pageSize}
          onClick={() => setPage(page + 1)}
        >next ›</button>
      </p>
    </div>
  )
}

export default TableBrowser
